begin;
create function pg_temp.statement_assert(ok boolean,label text)returns void language plpgsql as $$begin
 if ok is not true then raise exception 'FAIL: %',label;end if;
 perform set_config('folio.statement_checks',(coalesce(nullif(current_setting('folio.statement_checks',true),''),'0')::int+1)::text,true);
end$$;
create function pg_temp.statement_error(statement text,expected text,label text)returns void language plpgsql as $$begin
 begin execute statement;exception when others then
  if sqlstate<>expected then raise exception 'FAIL: % expected %, got %: %',label,expected,sqlstate,sqlerrm;end if;
  perform pg_temp.statement_assert(true,label);return;
 end;raise exception 'FAIL: % accepted',label;
end$$;
with u as(insert into auth.users(id,email)values(gen_random_uuid(),'statement-a@example.invalid')returning id)select set_config('folio.statement_a',id::text,true)from u;
with u as(insert into auth.users(id,email)values(gen_random_uuid(),'statement-b@example.invalid')returning id)select set_config('folio.statement_b',id::text,true)from u;
set local role authenticated;
select set_config('request.jwt.claim.sub',current_setting('folio.statement_a'),true);
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('folio.statement_a'),'is_anonymous',false)::text,true);
select public.initialize_workspace();
with a as(insert into public.accounts(name,type,opening_balance_paise)values('Synthetic statement bank','bank',500000)returning id)select set_config('folio.statement_bank',id::text,true)from a;
select set_config('folio.statement_category',(select id::text from public.categories where kind='expense' limit 1),true);
select set_config('folio.statement_rows',jsonb_build_array(jsonb_build_object('source_row','1:4','entry',jsonb_build_object('occurred_on',folio_private.today(),'kind','expense','amount_paise',10029,'category_id',current_setting('folio.statement_category'),'description','Synthetic statement lunch')))::text,true);
select set_config('folio.statement_request',gen_random_uuid()::text,true);
select pg_temp.statement_assert(public.preview_statement_import(current_setting('folio.statement_bank')::uuid,repeat('a',64),current_setting('folio.statement_rows')::jsonb)->'duplicates'='[false]'::jsonb,'new row preview');
select pg_temp.statement_assert((select count(*)=0 from public.transactions),'preview never posts money');
select pg_temp.statement_assert(public.import_statement_entries(current_setting('folio.statement_bank')::uuid,repeat('a',64),current_setting('folio.statement_rows')::jsonb,current_setting('folio.statement_request')::uuid)='{"inserted":1,"skipped":0}'::jsonb,'one confirmed row imported');
select pg_temp.statement_assert(public.import_statement_entries(current_setting('folio.statement_bank')::uuid,repeat('a',64),current_setting('folio.statement_rows')::jsonb,current_setting('folio.statement_request')::uuid)='{"inserted":1,"skipped":0}'::jsonb,'same request returns original result');
select pg_temp.statement_assert(public.import_statement_entries(current_setting('folio.statement_bank')::uuid,repeat('a',64),current_setting('folio.statement_rows')::jsonb,gen_random_uuid())='{"inserted":0,"skipped":1}'::jsonb,'same document row cannot repost with a new request');
select pg_temp.statement_assert((public.workspace_snapshot()->'summary'->>'expense_paise')::bigint=10029,'monthly spending counts once');
select pg_temp.statement_assert((select balance_paise=489971 from jsonb_to_recordset(public.workspace_snapshot()->'accounts')as a(balance_paise bigint)),'account balance exact to paise');
select pg_temp.statement_assert(public.preview_statement_import(current_setting('folio.statement_bank')::uuid,repeat('b',64),current_setting('folio.statement_rows')::jsonb)->'duplicates'='[true]'::jsonb,'another file with the same ledger charge is flagged');
select set_config('folio.statement_changed',jsonb_set(current_setting('folio.statement_rows')::jsonb,'{0,entry,description}','"Edited description"'::jsonb)::text,true);
select pg_temp.statement_assert(public.preview_statement_import(current_setting('folio.statement_bank')::uuid,repeat('a',64),current_setting('folio.statement_changed')::jsonb)->'duplicates'='[true]'::jsonb,'source marker survives description edits');
select pg_temp.statement_error(format('select public.import_statement_entries(%L,repeat(''a'',64),%L,%L)',current_setting('folio.statement_bank'),current_setting('folio.statement_changed'),current_setting('folio.statement_request')),'P0001','changed retry payload denied');
select pg_temp.statement_error(format('select public.preview_statement_import(%L,''bad-hash'',%L)',current_setting('folio.statement_bank'),current_setting('folio.statement_rows')),'P0001','bad document fingerprint rejected');
select pg_temp.statement_error(format('select public.preview_statement_import(%L,repeat(''a'',64),%L)',current_setting('folio.statement_bank'),(current_setting('folio.statement_rows')::jsonb||current_setting('folio.statement_rows')::jsonb)::text),'P0001','repeated source ID rejected');
select pg_temp.statement_error('select * from folio_private.statement_rows','42501','source markers not browser-readable');
select pg_temp.statement_error('select * from folio_private.statement_requests','42501','request receipts not browser-readable');
select set_config('request.jwt.claim.sub',current_setting('folio.statement_b'),true);
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('folio.statement_b'),'is_anonymous',false)::text,true);
select pg_temp.statement_error(format('select public.preview_statement_import(%L,repeat(''a'',64),%L)',current_setting('folio.statement_bank'),current_setting('folio.statement_rows')),'42501','second owner cannot preview another account');
select pg_temp.statement_error(format('select public.import_statement_entries(%L,repeat(''a'',64),%L,gen_random_uuid())',current_setting('folio.statement_bank'),current_setting('folio.statement_rows')),'42501','second owner cannot import to another account');
select set_config('request.jwt.claim.sub',current_setting('folio.statement_a'),true);
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('folio.statement_a'),'is_anonymous',true)::text,true);
select pg_temp.statement_error(format('select public.preview_statement_import(%L,repeat(''a'',64),%L)',current_setting('folio.statement_bank'),current_setting('folio.statement_rows')),'42501','anonymous JWT rejected');
select set_config('request.jwt.claims',jsonb_build_object('sub',current_setting('folio.statement_a'),'is_anonymous',false)::text,true);
select pg_temp.statement_error(format('select public.preview_statement_import(%L,repeat(''a'',64),%L)',current_setting('folio.statement_bank'),jsonb_build_array(jsonb_build_object('source_row','1:5','entry',(current_setting('folio.statement_rows')::jsonb->0->'entry')||'{"raw_pdf":"not allowed"}'::jsonb))::text),'P0001','raw document fields never accepted');
select public.delete_entry((select id from public.transactions limit 1),gen_random_uuid());
select pg_temp.statement_assert(public.preview_statement_import(current_setting('folio.statement_bank')::uuid,repeat('a',64),current_setting('folio.statement_rows')::jsonb)->'duplicates'='[true]'::jsonb,'deleting a settled charge does not cause silent source reimport');
select set_config('folio.statement_range',jsonb_build_array(jsonb_build_object('source_row','1:5','entry',(current_setting('folio.statement_rows')::jsonb->0->'entry')||'{"amount_paise":10030,"description":"Range fixture"}'::jsonb))::text,true);
update public.accounts set opening_balance_paise=-1000000000000 where id=current_setting('folio.statement_bank')::uuid;
select pg_temp.statement_error(format('select public.import_statement_entries(%L,repeat(''c'',64),%L,gen_random_uuid())',current_setting('folio.statement_bank'),current_setting('folio.statement_range')),'22003','unsupported financial aggregate rolls back the batch');
select pg_temp.statement_assert((select count(*)=0 from public.transactions),'no partial posting after range failure');
reset role;
select pg_temp.statement_assert((select count(*)=0 from folio_private.statement_rows where user_id=current_setting('folio.statement_a')::uuid and source_sha256=repeat('c',64)),'no source marker after failed posting');
select current_setting('folio.statement_checks')||' statement assertions passed';
rollback;
